def f(x):
    return sin(x)
def pi():
    while True:
        n = int(input("choisir  n : "))
        if 10 <= n <= 100:
            break
    a = int(input("choisir a : "))
    b = int(input("choisir b :" ))
    T = [{}]*n
    e = {}
    x = int(input("choisir le valeur initiative de  x : "))
    s = f(x)
    p = abs(a-b)/n
    for i in range(n):
        e = {}
        e["ab"] = x
        e["img"] = f(x)
        T[i] = e
        x += p 
        if abs(s) > abs(T[i]["img"]):
            s = T[i]["img"]
            k = T[i]["ab"]
    for i in range(n):
        print("abscisse : ",T[i]["ab"],"son image : ",T[i]["img"])
    print("La valeur approchée de pi est : ",k)
pi()

